// C11 (N8N-2.9): what to write to asox-metrics, pure (no call here).
// Input: {alert_id, mode: 'create' | 'update', fields, source, attack_run_id,
// config}. Only the template's fields go out (the mapping is strict: any other
// field is a 400), nulls dropped, times as ISO 8601 UTC, alert_id a string.
// Fields in lib-config metrics.first_time_fields are written only when the
// document doesn't have them yet (painless script, "Request").
function toIso(v) {
  let x = v;
  if (typeof x === 'string' && /^\d+$/.test(x.trim())) x = Number(x);
  // Wazuh writes "+0000"; JavaScript wants "+00:00".
  if (typeof x === 'string') x = x.trim().replace(/([+-]\d{2})(\d{2})$/, '$1:$2');
  if (typeof x !== 'number' && typeof x !== 'string') return null;
  const d = new Date(x);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}
// The filter: template fields only, typed as the template types them.
function cleanFields(fields, types) {
  const out = {};
  const dropped = [];
  for (const [k, v] of Object.entries(fields ?? {})) {
    const t = types[k];
    if (!t) { dropped.push(`${k} (not in the template)`); continue; }
    if (v === null || v === undefined || v === '') continue;
    let c = null;
    if (t === 'keyword') c = ['string', 'number', 'boolean'].includes(typeof v) ? String(v) : null;
    else if (t === 'integer') {
      const n = typeof v === 'string' && /^-?\d+$/.test(v.trim()) ? Number(v) : v;
      c = Number.isInteger(n) ? n : null;
    } else if (t === 'boolean') c = typeof v === 'boolean' ? v : null;
    else if (t === 'date') c = toIso(v);
    if (c === null) { dropped.push(`${k} (not a valid ${t})`); continue; }
    out[k] = c;
  }
  return { out, dropped };
}

const input = $input.first().json;
const m = input.config?.metrics;
const alertId = input.alert_id === null || input.alert_id === undefined ? '' : String(input.alert_id).trim();
const done = (result) => [{ json: { action: 'done', result: { alert_id: alertId || null, mode: input.mode ?? null, ...result } } }];
const failed = (cls, message) => done({ ok: false, class: cls, message, line: `metrics: failed (${cls})` });
const skipped = (why) => done({ ok: true, skipped: why, line: `metrics: skipped (${why})` });
if (!m || !m.fields) return failed('invalid_input', 'lib-metrics-upsert needs the lib-config output as `config`');
if (m.enabled === false) return skipped('disabled in lib-config');
const mode = input.mode;
if (mode !== 'create' && mode !== 'update') return failed('invalid_input', `mode must be "create" or "update", not ${JSON.stringify(mode)}`);
if (!alertId) return skipped('no Wazuh alert id');
const source = typeof input.source === 'string' ? input.source : null;
// C11 clarification: no document for test alerts (asox-test, the C3 check's
// contract-check alert); chk-metrics writes its own test document itself.
if (source !== null && m.skip_sources.includes(source)) return skipped(`test source ${source}`);

const { out, dropped } = cleanFields({ ...(input.fields ?? {}), alert_id: alertId }, m.fields);
const set = {};
const once = {};
for (const [k, v] of Object.entries(out)) (m.first_time_fields.includes(k) ? once : set)[k] = v;
if (mode === 'update' && Object.keys(set).length + Object.keys(once).length <= 1) return skipped('nothing to write');
const run = mode === 'create' && m.attack_start?.enabled === true && typeof input.attack_run_id === 'string'
  && /^[0-9A-Za-z-]{8,64}$/.test(input.attack_run_id) && once.t_attack_start === undefined ? input.attack_run_id : null;
return [{ json: {
  action: 'write', alert_id: alertId, mode, set, once, dropped, attack_run_id: run,
  attack: m.attack_start ?? null,
  policy: { index: m.index, timeout_ms: m.timeout_ms, retry_waits_s: m.retry_waits_s },
} }];

// The update request. One painless script for both modes: `set` fields are
// written, `once` fields only when the document doesn't have them (t_alert is
// never overwritten, t_ack stays the first acknowledgement). mode create =
// scripted upsert (the script also builds a missing document); mode update =
// no upsert, so a missing document is a 404 and nothing is created.
const p = $('Prepare').first().json;
const once = { ...p.once };
const notes = [];
let attackStart = null;
if ($('Find attack start').isExecuted) {
  // t_attack_start (lab scenarios, X-32): the first attack-start marker (rule
  // 100101) whose data.run_id is the asox_run id in the alert's log line, and
  // only inside the window t_event - window_s .. t_event (lib-config
  // metrics.attack_start.window_s, 3600): a replayed fixture keeps its old run
  // id, whose marker would give a MTTD of days (A99 finding). Outside the
  // window, or without t_event, t_attack_start stays empty and the reason is
  // in notes and attack_start. The input is the lookup's answer from either
  // output (error output: {error}).
  const r = $input.first().json;
  const parse = (ts) => {
    const x = typeof ts === 'string' ? new Date(ts.trim().replace(/([+-]\d{2})(\d{2})$/, '$1:$2')) : null;
    return x && !Number.isNaN(x.getTime()) ? x : null;
  };
  const windowS = Number(p.attack?.window_s ?? 3600);
  const tEvent = typeof once.t_event === 'string' ? new Date(once.t_event) : null;
  const markers = r.statusCode === 200 && Array.isArray(r.body?.hits?.hits)
    ? r.body.hits.hits.map((h) => parse(h?._source?.timestamp)).filter((d) => d !== null) : [];
  let reason = null;
  let used = null;
  if (r.statusCode !== 200) reason = `lookup failed (${r.statusCode ?? 'connection error'})`;
  else if (markers.length === 0) reason = `no marker for run ${p.attack_run_id} (yet)`;
  else if (!tEvent || Number.isNaN(tEvent.getTime())) reason = `marker found but no t_event to check the ${windowS} s window against`;
  else {
    used = markers.find((d) => d.getTime() <= tEvent.getTime() && d.getTime() >= tEvent.getTime() - windowS * 1000) ?? null;
    if (!used) {
      const m = markers[0];
      const ds = Math.round((tEvent.getTime() - m.getTime()) / 1000);
      reason = ds < 0
        ? `marker of run ${p.attack_run_id} at ${m.toISOString()} is ${-ds} s after t_event ${tEvent.toISOString()}`
        : `marker of run ${p.attack_run_id} at ${m.toISOString()} is ${ds} s before t_event ${tEvent.toISOString()}, outside the ${windowS} s window`;
    }
  }
  if (used) once.t_attack_start = used.toISOString();
  else notes.push(`attack start: ${reason}; t_attack_start left empty`);
  attackStart = { run_id: p.attack_run_id, window_s: windowS, markers: markers.length,
    t_attack_start: used ? used.toISOString() : null, reason };
}
const SCRIPT = [
  'boolean changed = false;',
  'for (e in params.set.entrySet()) { if (ctx._source[e.getKey()] != e.getValue()) { ctx._source[e.getKey()] = e.getValue(); changed = true; } }',
  'for (e in params.once.entrySet()) { if (ctx._source[e.getKey()] == null) { ctx._source[e.getKey()] = e.getValue(); changed = true; } }',
  "if (!changed) { ctx.op = 'noop'; }",
].join(' ');
const body = { script: { lang: 'painless', source: SCRIPT, params: { set: p.set, once } } };
if (p.mode === 'create') { body.scripted_upsert = true; body.upsert = {}; }
return [{ json: { body, notes, attack_start: attackStart, once_fields: Object.keys(once) } }];

// Retry policy for the indexer (C11; lib-config metrics): a connection error,
// a timeout or HTTP 5xx -> wait and call again (retry_waits_s: 2 more calls);
// anything else is answered and classified in "Result". A certificate error
// is a configuration problem (CA not mounted, wrong host name): not retried.
const r = $input.first().json;
const policy = $('Prepare').first().json.policy;
const attempt = $runIndex + 1; // this node runs once per call
const status = typeof r.statusCode === 'number' ? r.statusCode : null;
const thrown = r.error !== undefined && status === null; // HTTP node error output
const text = thrown ? JSON.stringify(r.error) : '';
const TLS = /CERT|certificate|self[- ]signed|UNABLE_TO_VERIFY|ALTNAME/i;
const NETWORK = /ECONNREFUSED|ENOTFOUND|EAI_AGAIN|ETIMEDOUT|ECONNRESET|EHOSTUNREACH|ENETUNREACH|ECONNABORTED|timeout|timed out|socket hang up|connection cannot be established/i;
const cls = thrown ? (TLS.test(text) ? 'config' : (NETWORK.test(text) ? 'unreachable' : 'error'))
  : (status >= 500 ? 'server_error' : null);
const transient = cls === 'unreachable' || cls === 'server_error';
const calls = policy.retry_waits_s.length + 1;
if (transient && attempt < calls) {
  return [{ json: { decision: 'retry', attempt, wait_s: policy.retry_waits_s[attempt - 1], reason: cls } }];
}
if (cls !== null) {
  const e = r.error;
  const detail = thrown
    ? (typeof e === 'string' ? e : [e?.message, e?.description].filter(Boolean).join(': ') || text)
    : `HTTP ${status}: ${typeof r.body === 'string' ? r.body : JSON.stringify(r.body)}`;
  return [{ json: { decision: 'error', class: cls, attempts: attempt, http_status: status,
    message: `${detail}`.slice(0, 500) + (transient ? ` (${attempt} calls)` : '') } }];
}
return [{ json: { decision: 'response', statusCode: status, body: r.body, attempts: attempt } }];

// {ok, line} for the caller's summary: "metrics: ok", "metrics: skipped
// (<why>)" or "metrics: failed (<class>)". Never throws: a metrics failure
// must not stop a playbook or an event route (N8N-2.9).
const p = $('Prepare').first().json;
const q = $('Request').first().json;
const a = $input.first().json;
const base = { alert_id: p.alert_id, mode: p.mode, attempts: a.attempts ?? null, dropped: p.dropped, notes: q.notes, attack_start: q.attack_start ?? null };
const fail = (cls, extra) => [{ json: { ok: false, class: cls, ...base, ...extra, line: `metrics: failed (${cls})` } }];
if (a.decision === 'error') return fail(a.class, { http_status: a.http_status, message: a.message });
const st = a.statusCode;
const err = a.body?.error ?? null;
const message = `HTTP ${st}: ${err?.type ?? ''} ${err?.reason ?? (typeof a.body === 'string' ? a.body : '')}`.trim().slice(0, 500);
if (st === 200 || st === 201) {
  return [{ json: { ok: true, result: a.body?.result ?? null, ...base,
    written: { set: Object.keys(p.set), once_if_missing: q.once_fields }, line: 'metrics: ok' } }];
}
// mode update: no document for this Wazuh alert (an alert from before
// N8N-2.9, or one n8n didn't create): nothing to update, nothing created.
if (st === 404 && err?.type === 'document_missing_exception') {
  return [{ json: { ok: true, skipped: 'no-document', ...base, line: 'metrics: skipped (no document)' } }];
}
// 400 (strict mapping, bad value), 401 / 403 (credential, role), 404 on the
// index (missing: bootstrap.sh core creates it, never n8n): configuration
// errors, not retried.
if ([400, 401, 403, 404].includes(st)) return fail('config', { http_status: st, message });
if (st === 409) return fail('conflict', { http_status: st, message });
return fail(`http_${st}`, { http_status: st, message });
